/* Protótipo acadêmico independente. Nenhum servidor, autenticação real, IA ou banco compartilhado. */
(() => {
'use strict';
const KEY='fluxocontabil_tcc_demo_v1';
let focusedAlertId=null;
const NAV=[['dashboard','Visão geral','dashboard'],['empresas','Empresas-clientes','building'],['equipe','Equipe do escritório','users'],['checklist','Checklist mensal','check'],['lancamentos','Lançamentos','layers'],['conferencias','Conferências','scan'],['alertas','Alertas','bell'],['auditoria','Auditoria','history'],['encerramento','Fechamento mensal','lock'],['roteiro','Roteiro de teste','book'],['avaliacao','Avaliar protótipo','message']];
const ICONS={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',building:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M9 21v-4h6v4M8 7h2m4 0h2M8 11h2m4 0h2"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',check:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 12 2.5 2.5L16 9"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 17l9 5 9-5"/>',scan:'<path d="M7 3H5a2 2 0 0 0-2 2v2m14-4h2a2 2 0 0 1 2 2v2M7 21H5a2 2 0 0 1-2-2v-2m14 4h2a2 2 0 0 0 2-2v-2"/><path d="m8 12 2.5 2.5L16 9"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',history:'<path d="M3 12a9 9 0 1 0 2.64-6.36L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/>',lock:'<rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 1 1 8 0v4"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5v14ZM4 19.5A2.5 2.5 0 0 0 6.5 22H20"/>',message:'<path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8A8.5 8.5 0 0 1 12.5 20a8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8A8.5 8.5 0 0 1 12.5 3a8.5 8.5 0 0 1 8.5 8.5Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',alert:'<path d="m10.3 3.7-8.2 14.5A2 2 0 0 0 3.8 21h16.4a2 2 0 0 0 1.7-2.8L13.7 3.7a2 2 0 0 0-3.4 0ZM12 9v4m0 4h.01"/>',spark:'<path d="m12 3 1.9 6.1L20 11l-6.1 1.9L12 19l-1.9-6.1L4 11l6.1-1.9L12 3ZM19 18v4m-2-2h4"/>',brief:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>'};
const icon=(name,size=18)=>`<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.spark}</svg>`;
const e=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brl=(n)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
const dshort=(iso)=>new Date(iso).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});
const uid=()=>`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
const baseNames=['Receber e organizar documentação','Conferir lançamentos do período','Conciliar saldos e razão auxiliar','Verificar impostos e provisões','Revisar alertas e justificativas','Validar fechamento mensal'];
function tasks(prefix,count,owner=''){return baseNames.map((title,i)=>({id:`${prefix}-t${i+1}`,title,done:i<count,owner,due:'',doneAt:null}));}
function fresh(){return {role:'GESTOR',section:'dashboard',company:'c1',companies:[
{id:'c1',name:'Alvorada Comércio Ltda.',sector:'Comércio',responsavel:'Paulo Nogueira',month:'10/2026',closed:false,tasks:tasks('c1',2,'Paulo Nogueira'),balance:{contabil:6000,auxiliar:4000}},
{id:'c2',name:'Horizonte Serviços Ltda.',sector:'Serviços',responsavel:'Camila Rocha',month:'10/2026',closed:false,tasks:tasks('c2',4,'Camila Rocha'),balance:{contabil:4750,auxiliar:4750}},
{id:'c3',name:'Vale Verde Indústria Ltda.',sector:'Indústria',responsavel:'Paulo Nogueira',month:'10/2026',closed:true,closedAt:null,closedBy:'Não informado (cenário inicial)',tasks:tasks('c3',6,'Paulo Nogueira'),balance:{contabil:9500,auxiliar:9500}}],team:[{id:'u1',name:'Marina Oliveira',role:'GESTOR'},{id:'u2',name:'Paulo Nogueira',role:'CONTADOR'},{id:'u3',name:'Camila Rocha',role:'CONTADOR'}],entries:[{id:'l1',company:'c1',date:'2026-10-20',account:'Despesas operacionais',description:'Despesa mensal fora do padrão habitual',value:7800},{id:'l2',company:'c1',date:'2026-09-20',account:'Despesas operacionais',description:'Despesa habitual de referência',value:1200},{id:'l3',company:'c2',date:'2026-10-16',account:'Serviços contratados',description:'Prestação de serviços',value:2100},{id:'l4',company:'c3',date:'2026-10-08',account:'Fornecedores',description:'Compra de insumos',value:1850}],alerts:[
{id:'a1',company:'c1',kind:'saldo',title:'Divergência entre saldos',description:'Saldo contábil de R$ 6.000,00 e razão auxiliar de R$ 4.000,00. Diferença de R$ 2.000,00.',status:'Pendente',note:''},
{id:'a2',company:'c1',entryId:'l1',kind:'atipico',title:'Lançamento fora do habitual',description:'Lançamento de R$ 7.800,00 comparado a um valor habitual ilustrativo de R$ 1.200,00. Verifique a justificativa.',status:'Pendente',note:''}
],audit:[{id:'h1',date:'2026-11-24T09:42:00',actor:'Marina Oliveira (Gestor)',action:'Preparação da demonstração',detail:'Dados fictícios carregados para o estudo de uso.',company:'—'},{id:'h2',date:'2026-11-24T09:31:00',actor:'Paulo Nogueira (Contador)',action:'Conferência simulada',detail:'Divergência de R$ 2.000,00 sinalizada.',company:'Alvorada Comércio Ltda.'}],feedback:null};}
function load(){try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&Array.isArray(s.companies)&&Array.isArray(s.alerts)&&Array.isArray(s.team)){if(!s.userId||!s.team.some(m=>m.id===s.userId&&m.role===s.role))s.userId=s.team.find(m=>m.role===s.role)?.id;const initial=s.alerts.find(a=>a.id==='a2'&&a.kind==='atipico');if(initial&&!initial.entryId&&s.entries?.some(x=>x.id==='l1'))initial.entryId='l1';return s;}}catch(_err){}const s=fresh();s.userId='u1';return s;}
let st=load(), filter='Todos', toastTimer;
const OFFICE_KEY='fluxocontabil_tcc_offices_v7';
const OFFICE_NAMES={aurora:'Aurora Contábil',nova:'Violeta Contabilidade'};
function createSecondOffice(){const o=fresh();o.officeId='nova';o.officeName=OFFICE_NAMES.nova;o.role='GESTOR';o.userId='v1';o.team=[{id:'v1',name:'Renata Costa',role:'GESTOR'},{id:'v2',name:'Diego Lima',role:'CONTADOR'}];o.companies=[{id:'vc1',name:'Orquídea Serviços Ltda.',sector:'Serviços',responsavel:'Diego Lima',month:'10/2026',closed:false,tasks:tasks('vc1',1,'Diego Lima'),balance:{contabil:3200,auxiliar:3200}},{id:'vc2',name:'Cedro Comércio Ltda.',sector:'Comércio',responsavel:'Diego Lima',month:'10/2026',closed:false,tasks:tasks('vc2',3,'Diego Lima'),balance:{contabil:5500,auxiliar:5000}}];o.company='vc1';o.entries=[];o.alerts=[{id:'va1',company:'vc2',kind:'saldo',title:'Divergência entre saldos',description:'Diferença ilustrativa de R$ 500,00 entre registros.',status:'Pendente',note:''}];o.audit=[];o.feedback=null;return o;}
function allOffices(){try{const v=JSON.parse(localStorage.getItem(OFFICE_KEY)||'null');if(v&&v.aurora&&v.nova)return v;}catch(_e){}const first=st;first.officeId='aurora';first.officeName=OFFICE_NAMES.aurora;return {aurora:first,nova:createSecondOffice()};}
let officeStates=allOffices();
if(!st.officeId)st.officeId='aurora';
if(!st.officeName)st.officeName=OFFICE_NAMES[st.officeId]||OFFICE_NAMES.aurora;
if(officeStates[st.officeId])st=officeStates[st.officeId];
const MONTH_OPTIONS=['09/2026','10/2026','11/2026'];
const cloneData=x=>JSON.parse(JSON.stringify(x));
function periodSnapshot(o){return {companies:cloneData(o.companies),entries:cloneData(o.entries||[]),alerts:cloneData(o.alerts||[])};}
function ensurePeriods(o){
 if(!o.activeMonth)o.activeMonth='10/2026';
 if(!o.periodSnapshots)o.periodSnapshots={};
 if(!o.periodSnapshots[o.activeMonth])o.periodSnapshots[o.activeMonth]=periodSnapshot(o);
 o.groups=Array.isArray(o.groups)?o.groups:[];
 o.calls=Array.isArray(o.calls)?o.calls:[];
}
function createEmptyPeriod(o,month){
 return {companies:cloneData(o.companies).map(c=>({...c,month,closed:false,closedAt:null,closedBy:null,closeEstimated:false,readyNotified:false,balance:{contabil:0,auxiliar:0},tasks:c.tasks.map(t=>({...t,id:uid(),done:false,doneAt:null,due:''}))})),entries:[],alerts:[]};
}
function switchMonth(month){
 if(!MONTH_OPTIONS.includes(month)||month===st.activeMonth)return;
 ensurePeriods(st);st.periodSnapshots[st.activeMonth]=periodSnapshot(st);
 if(!st.periodSnapshots[month])st.periodSnapshots[month]=createEmptyPeriod(st,month);
 const saved=cloneData(st.periodSnapshots[month]);
 st.companies=saved.companies;st.entries=saved.entries;st.alerts=saved.alerts;
 st.activeMonth=month;focusedAlertId=null;filter='Todos';
 if(!company(st.company))st.company=st.companies[0]?.id;
 log('Consulta de competência',`Competência ${month} selecionada; registros demonstrativos independentes por mês.`);
 render();toast(`Exibindo competência ${month}.`);
}
function migrateOffice(o){
 o.messages=Array.isArray(o.messages)?o.messages:[];
 o.notifications=Array.isArray(o.notifications)?o.notifications:[];
 o.team.forEach(m=>{m.publicBio??='';m.specialty??=(m.role==='CONTADOR'?'Conciliação e fechamento contábil':'Gestão de processos contábeis');m.contactVisibility??='restrito';});
 o.companies.forEach(c=>{c.readyNotified??=false;c.tasks.forEach(t=>{if(!t.owner)t.owner=c.responsavel||'';if(t.done&&!t.doneAt)t.doneAt=null;if(!t.done)t.doneAt=null;});});
 if(o.officeId==='aurora'){const historical=o.companies.find(c=>c.id==='c3');if(historical?.closed&&!historical.closedAt){historical.closedAt=null;historical.closedBy='Não informado (cenário inicial)';historical.closeEstimated=true;}}
 return o;
}
Object.values(officeStates).forEach(o=>{migrateOffice(o);ensurePeriods(o);});st=migrateOffice(st);ensurePeriods(st);
function switchOffice(id){if(isLoginMode()||!isGestor()||!officeStates[id]||id===st.officeId)return;st.periodSnapshots[st.activeMonth]=periodSnapshot(st);officeStates[st.officeId]=st;const previous=actor();st=officeStates[id];if(!st.team.some(m=>m.id===st.userId&&m.role===st.role)){st.role='GESTOR';st.userId=st.team.find(m=>m.role==='GESTOR')?.id;}st.section='dashboard';focusedAlertId=null;filter='Todos';log('Troca de cenário de escritório',`Cenário selecionado: ${st.officeName}; operação ilustrativa iniciada por ${previous}.`);render();toast(`Cenário fictício: ${st.officeName}.`);}

const SESSION_KEY='fluxocontabil_demo_session_v5';
function activeSession(){try{return JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null')}catch{return null}}
const isLoginMode=()=>activeSession()?.mode==='local';
function enforceSession(){
 const session=activeSession();
 if(session?.mode!=='local'||!session.accountId)return;
 // O cadastro local não concede acesso a um perfil gerencial; é sempre Contador demonstrativo.
 if(st.officeId!=='aurora'&&officeStates.aurora){st=officeStates.aurora;}
 const id='local-account:'+session.accountId;
 let user=st.team.find(m=>m.id===id);
 if(!user){user={id,name:session.label,role:'CONTADOR',specialty:'Participante demonstrativo',publicBio:'Perfil local de teste'};st.team.push(user);}
 else {user.name=session.label;user.role='CONTADOR';}
 st.role='CONTADOR';st.userId=id;
}
function enterGuestMode(){
 if(!officeStates.aurora)return;
 st=officeStates.aurora;st.role='GESTOR';st.userId=st.team.find(m=>m.role==='GESTOR')?.id;
}
const save=()=>{try{ensurePeriods(st);st.periodSnapshots[st.activeMonth]=periodSnapshot(st);localStorage.setItem(KEY,JSON.stringify(st));officeStates[st.officeId||'aurora']=st;localStorage.setItem(OFFICE_KEY,JSON.stringify(officeStates));}catch(_err){}};
const activeUser=()=>st.team.find(m=>m.id===st.userId&&m.role===st.role)||st.team.find(m=>m.role===st.role);
const actor=()=>`${activeUser()?.name||'Usuário fictício'} (${st.role==='GESTOR'?'Gestor':'Contador'})`;
const canViewAudit=(ev)=>isGestor()||st.companies.some(c=>c.name===ev.company&&c.responsavel===activeUser()?.name)||ev.actor.startsWith(activeUser()?.name+' (');
const isGestor=()=>!isLoginMode()&&st.role==='GESTOR';
const current=()=>st.companies.find(c=>c.id===st.company)||st.companies[0];
const company=(id)=>st.companies.find(c=>c.id===id);
const historyOf=(a)=>Array.isArray(a.noteHistory)?a.noteHistory:[];
const canEditTask=(t)=>isGestor()||t.owner===activeUser()?.name;
const visibleTasks=(c)=>isGestor()?c.tasks:c.tasks.filter(t=>t.owner===activeUser()?.name);
const pending=(id)=>st.alerts.filter(a=>a.company===id&&a.status==='Pendente');
const allPending=()=>st.alerts.filter(a=>a.status==='Pendente');
const progress=(c)=>c.tasks.length?Math.round(c.tasks.filter(t=>t.done).length/c.tasks.length*100):100;
const blockers=(c)=>{const x=[];if(c.closed)return x;const left=c.tasks.filter(t=>!t.done).length;if(left)x.push(`${left} tarefa(s) do checklist pendente(s)`);if(Math.abs(c.balance.contabil-c.balance.auxiliar)>.00001)x.push(`Divergência de ${brl(Math.abs(c.balance.contabil-c.balance.auxiliar))} entre saldos`);const alerts=pending(c.id);if(alerts.length)x.push(`${alerts.length} alerta(s) ainda pendente(s) de análise`);return x;};
function notifyReady(){
 st.notifications??=[];
 for(const c of st.companies){
  const ready=!c.closed&&c.tasks.length>0&&c.tasks.every(t=>t.done)&&Math.abs(c.balance.contabil-c.balance.auxiliar)<.00001&&pending(c.id).length===0;
  if(ready&&!c.readyNotified){c.readyNotified=true;/* Avisos secundários omitidos na edição de avaliação; alertas contábeis permanecem ativos. */}
  if(!ready)c.readyNotified=false;
 }
 st.notifications=st.notifications.slice(0,80);
}
function log(action,detail,c){st.audit.unshift({id:uid(),date:new Date().toISOString(),actor:actor(),action,detail,company:c?.name||'—'});st.audit=st.audit.slice(0,180);}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
const badge=(label,color='gray')=>`<span class="badge ${color}"><i class="dot"></i>${e(label)}</span>`;
const head=(label,title,subtitle,action='')=>`<div class="page-head"><div><div class="eyebrow">${e(label)}</div><h1>${e(title)}</h1><p>${e(subtitle)}</p></div>${action}</div>`;
const btn=(act,label,cls='btn-primary',extra='')=>`<button type="button" data-action="${act}" class="btn ${cls}" ${extra}>${label}</button>`;
const empty=(title,text,emo='✦')=>`<div class="empty"><div class="empty-icon">${emo}</div><b>${e(title)}</b><p>${e(text)}</p></div>`;
const selector=()=>`<div class="selector-strip"><label for="companySelect">EMPRESA-CLIENTE</label><select id="companySelect" aria-label="Escolher empresa-cliente">${st.companies.map(c=>`<option value="${e(c.id)}" ${c.id===current().id?'selected':''}>${e(c.name)}</option>`).join('')}</select>${badge(current().closed?'Encerrado':'Em andamento',current().closed?'green':'purple')}</div>`;
const roleNote=()=>`<div class="role-banner">${icon('shield',19)} <span>Você está explorando como <b>${isGestor()?'Gestor':'Contador'}</b>. ${isGestor()?'Neste perfil, você pode administrar clientes e equipe, além de coordenar encerramentos.':'Neste perfil, você pode atualizar tarefas, lançamentos, conferências e alertas, mas não administrar clientes/equipe nem encerrar o mês.'} ${isLoginMode()?'<b>A conta de teste mostra somente o seu perfil. Para alternar entre gestores e contadores fictícios, saia e entre como Visitante.</b>':'<b>Você está no modo teste: alterne o perfil e o usuário fictício no canto superior direito.</b>'}</span></div>`;
const sample=`<span class="pill-note">Cenário ilustrativo · Competência ${e(st.activeMonth||'10/2026')}</span>`;
function renderNav(){document.getElementById('mainNav').innerHTML=NAV.map(([id,label,ico])=>`<button type="button" class="nav-item ${st.section===id?'active':''}" data-nav="${id}" ${st.section===id?'aria-current="page"':''}>${icon(ico)} <span>${e(label)}</span>${id==='alertas'&&allPending().length?`<span class="num">${allPending().length}</span>`:''}</button>`).join('');}
function kpi(label,value,foot,ico){return `<div class="card kpi"><div class="kpi-head"><span>${e(label)}</span><span class="kpi-icon">${icon(ico)}</span></div><div class="kpi-value number">${e(value)}</div><div class="kpi-foot">${foot}</div></div>`;}
function dashboard(){let total=st.companies.reduce((a,c)=>a+c.tasks.length,0),done=st.companies.reduce((a,c)=>a+c.tasks.filter(t=>t.done).length,0),pct=total?Math.round(100*done/total):100;return `
<div class="hero"><div class="eyebrow">BEM-VINDO À DEMONSTRAÇÃO</div><h1>Mais clareza para cada fechamento mensal.</h1><p>Conheça a proposta de organização dos processos, conferências e alertas inteligentes para escritórios contábeis.</p><div class="btn-row">${btn('go-roteiro',`${icon('arrow')} Começar roteiro`,'btn-outline')} ${btn('go-conferencias','Explorar conferências','btn-soft')}</div></div>
${roleNote()}
 
 <div class="grid kpi-grid">${kpi('Empresas-clientes',st.companies.length,'Neste escritório demonstrativo','building')}${kpi('Checklists concluídos',`${pct}%`,`${done} de ${total} tarefas`,'check')}${kpi('Alertas pendentes',allPending().length,'Atenção: não significam erro confirmado','bell')}${kpi('Fechamentos encerrados',st.companies.filter(c=>c.closed).length,'Competência outubro/2026','lock')}</div>
<div class="grid cols-2"><section class="card"><div class="section-head"><div><h2>Andamento por empresa</h2><p class="section-sub">Acompanhe os checklists da competência</p></div><button type="button" class="link-btn" data-nav="empresas">Ver todas →</button></div>${st.companies.map(c=>`<div class="company-row"><span class="initials">${e(c.name.slice(0,2).toUpperCase())}</span><div><div class="cname">${e(c.name)}</div><small>${e(c.responsavel)} · ${e(c.month)}</small></div><div class="cprog"><div class="progress-label"><span>Checklist</span><b>${progress(c)}%</b></div><div class="progress"><i style="width:${progress(c)}%"></i></div></div>${badge(c.closed?'Encerrado':progress(c)===100?'Pronto p/ revisão':'Em andamento',c.closed?'green':progress(c)===100?'purple':'orange')}</div>`).join('')}</section>
<section class="card"><div class="section-head"><div><h2>Pontos de atenção</h2><p class="section-sub">Alertas do cenário de demonstração</p></div><button type="button" class="link-btn" data-nav="alertas">Ver alertas →</button></div>${allPending().length?allPending().slice(0,3).map(a=>`<div class="alert-item"><div class="alert-symbol">${icon('alert')}</div><div class="alert-content"><b>${e(a.title)}</b><p>${e(company(a.company)?.name||'')} · ${e(a.description)}</p><div class="alert-meta">${badge('Aguardando análise','orange')}</div></div></div>`).join(''):empty('Nenhum alerta pendente','Os alertas demonstrativos já foram analisados.','✓')}<div class="soft-callout mt"><b>Importante:</b> esta tela representa o funcionamento pretendido. A sinalização estatística é simulada, sem execução de modelos de IA.</div></section></div>
<div class="grid cols-even mt"><div class="card"><div class="section-head"><h2>Como funciona a proposta?</h2>${icon('spark',22)}</div><div class="step-list">${[['1','Organize','Escritório, equipe, empresas-clientes e competência.'],['2','Confira','Checklists, lançamentos e comparação de saldos.'],['3','Investigue','Alertas indicam dados que merecem revisão profissional.']].map(([n,t,d])=>`<div style="display:flex;gap:12px"><span class="step-number">${n}</span><div><b>${t}</b><p class="fine" style="margin:2px 0">${d}</p></div></div>`).join('')}</div></div><div class="card"><h2>O que testar primeiro?</h2><p class="section-sub">Experimente o fluxo com dados fictícios e depois registre sua opinião.</p><div class="figure-mini mt" aria-hidden="true"><i style="height:32%"></i><i style="height:45%"></i><i style="height:70%"></i><i style="height:63%"></i><i style="height:92%"></i><i style="height:55%"></i><i style="height:79%"></i></div><div class="btn-row mt">${btn('go-roteiro','Ver roteiro','btn-primary')}${btn('go-avaliacao','Avaliar experiência','btn-outline')}</div></div></div>`;}
function empresas(){return `${head('CADASTROS','Empresas-clientes','Organizações atendidas pelo escritório. Os dados abaixo são integralmente fictícios.',isGestor()?btn('add-company',`${icon('plus')} Nova empresa`):'')}${roleNote()}<section class="card"><div class="section-head"><h2>Carteira do escritório</h2>${badge(`${st.companies.length} empresas`,'purple')}</div><div class="table-scroll"><table><thead><tr><th>Empresa-cliente</th><th>Setor</th><th>Responsável</th><th>Checklist</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${st.companies.map(c=>`<tr><td class="td-main">${e(c.name)}<span class="td-sub">Competência ${e(c.month)}</span></td><td>${e(c.sector)}</td><td>${e(c.responsavel)}</td><td><b>${progress(c)}%</b><div class="progress" style="width:86px;margin-top:5px"><i style="width:${progress(c)}%"></i></div></td><td>${badge(c.closed?'Encerrada':'Em andamento',c.closed?'green':'orange')}</td><td><button type="button" class="link-btn" data-company-open="${e(c.id)}">Abrir →</button>${isGestor()?btn("change-owner:"+c.id,"Responsável","btn-outline btn-sm"):""}</td></tr>`).join('')}</tbody></table></div></section><div class="soft-callout mt">${icon('shield',16)} <b>Permissões:</b> somente Gestor cadastra e administra empresas-clientes. O Contador trabalha nos fechamentos das empresas vinculadas ao escritório.</div>`;}
function equipe(){return `${head('ADMINISTRAÇÃO','Equipe do escritório','Perfis profissionais fictícios: não exibimos senhas, contatos pessoais nem dados sensíveis.',isGestor()?btn('add-member',`${icon('plus')} Novo funcionário`):'')}${roleNote()}<div class="grid cols-2"><section class="card"><div class="section-head"><h2>Membros de ${e(st.officeName)}</h2>${badge(`${st.team.length} integrantes`,'purple')}</div>${st.team.map(m=>`<div class="team-row"><div class="initials">${e(m.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</div><div class="team-name">${e(m.name)}<small>${m.role==='GESTOR'?'Gestão do escritório':'Atividades contábeis'}</small></div>${badge(m.role==='GESTOR'?'Gestor':'Contador',m.role==='GESTOR'?'purple':'gray')}${isGestor()||m.id===st.userId?btn('member-profile:'+m.id,'Ver perfil','btn-outline btn-sm'):''}${isGestor()?btn('remove-member:'+m.id,'Retirar','btn-danger btn-sm'):''}</div>`).join('')}</section><section class="card"><h2>Permissões e privacidade</h2><div class="soft-callout mt">O Gestor pode consultar dados <b>profissionais</b> dos integrantes: função, especialidade, atividades e empresas designadas. Dados pessoais, senhas e mensagens privadas não aparecem no perfil.</div><div class="soft-callout mt">Ao trocar o funcionário demonstrativo, as tarefas são filtradas por responsável. O gestor visualiza a carteira completa. A troca de papéis continua sendo uma simulação local e não representa autorização real.</div></section></div>`;}
function memberProfile(){return '';}
function mensagens(){
 st.messages??=[];st.groups??=[];st.calls??=[];
 const me=activeUser(), people=st.team.filter(m=>m.id!==me?.id);
 const groups=st.groups.filter(g=>g.members.includes(me?.id));
 const channels=[...people.map(m=>({id:'dm:'+m.id,name:m.name,detail:m.role==='GESTOR'?'Gestor':'Contador',avatar:m.name.split(' ').map(x=>x[0]).slice(0,2).join(''),group:false})),...groups.map(g=>({id:'group:'+g.id,name:g.name,detail:`${g.members.length} integrantes`,avatar:'♣',group:true}))];
 if(!channels.some(c=>c.id===st.chatChannel))st.chatChannel=channels[0]?.id||'';
 const selected=channels.find(c=>c.id===st.chatChannel),isGroup=selected?.group;
 const group=isGroup?st.groups.find(g=>'group:'+g.id===st.chatChannel):null;
 const other=!isGroup?people.find(m=>'dm:'+m.id===st.chatChannel):null;
 const messages=st.messages.filter(m=>isGroup?m.groupId===group?.id:!m.groupId&&[m.from,m.to].every(id=>[me?.id,other?.id].includes(id)));
 const lastCalls=st.calls.filter(c=>c.by===me?.id||c.target===st.chatChannel).slice(-5).reverse();
 return `${head('COMUNICAÇÃO INTERNA','Conversas da equipe','Mensagens, grupos e chamadas demonstrativas. Sem envio para outros dispositivos.')}
 <section class="chat-app" aria-label="Bate-papo demonstrativo">
 <aside class="chat-list-pane"><div class="chat-list-top"><div><b>Conversas</b><small> ${e(st.officeName)}</small></div>${btn('new-group','+ Novo grupo','btn-primary btn-sm')}</div>
 <div class="chat-search"><input class="input" id="chatSearch" placeholder="Buscar conversa" aria-label="Buscar conversa"></div>
 <div id="chatContactList">${channels.map(c=>`<button type="button" class="chat-contact ${c.id===st.chatChannel?'selected':''}" data-chat-channel="${e(c.id)}"><span class="chat-avatar">${e(c.avatar)}</span><span class="chat-contact-text"><strong>${e(c.name)}</strong><small>${e(c.detail)}</small></span><span class="chat-contact-tail">›</span></button>`).join('')||'<p class="fine muted" style="padding:15px">Adicione integrantes para conversar.</p>'}</div>
 <div class="chat-local-label">🔒 Conversas salvas apenas neste navegador</div></aside>
 <div class="chat-conversation">${selected?`<div class="chat-conv-header"><div class="chat-avatar">${e(selected.avatar)}</div><div class="chat-conv-identity"><strong>${e(selected.name)}</strong><small>${e(selected.detail)} · conversa fictícia</small></div><div class="chat-conv-actions">${isGroup?btn('group-members:'+group.id,'Integrantes','btn-outline btn-sm'):''}${btn('call:audio','☎ Áudio','btn-outline btn-sm')}${btn('call:video','▣ Vídeo','btn-outline btn-sm')}</div></div>
 <div class="chat-message-area" id="chatMessageArea"><div class="chat-date-note">Mensagens apenas para demonstração; não são transmitidas</div>${messages.length?messages.map(m=>`<div class="chat-message ${m.from===me.id?'sent':''}"><strong>${e(st.team.find(x=>x.id===m.from)?.name||'Integrante')}</strong><p>${e(m.body)}</p><time>${e(dshort(m.date))}</time></div>`).join(''):`<div class="chat-empty-state">✉<strong>Comece a conversa</strong><span>Escreva uma mensagem de teste com dados fictícios.</span></div>`}</div>
 <form id="chatForm" class="chat-compose"><div class="emoji-strip">${['😊','👍','✅','📌','💜'].map(em=>`<button type="button" data-emoji="${em}" title="Inserir emoji">${em}</button>`).join('')}</div><div class="chat-compose-row"><textarea id="chatMessage" name="body" placeholder="Digite uma mensagem fictícia..." maxlength="500" rows="2" required></textarea><button type="submit" class="btn btn-primary">Enviar ➤</button></div></form>
 <details class="chat-call-history"><summary>Histórico de chamadas demonstrativas (${lastCalls.length})</summary>${lastCalls.map(c=>`<div>${e(c.type==='video'?'Vídeo':'Voz')} · ${e(c.name)} · ${e(dshort(c.date))} · Não conectada</div>`).join('')||'<p>Nenhuma tentativa de chamada.</p>'}</details>`:`<div class="chat-empty-state">Escolha uma conversa ou crie um grupo.</div>`}</div></section>
 <div class="inline-note mt">**Limitação:** grupos, mensagens e histórico de chamadas ficam neste navegador. Os botões de voz e vídeo demonstram a interface, mas não estabelecem chamadas reais. Não insira dados sensíveis.</div>`;
}

function checklist(){const c=current(),mine=visibleTasks(c);return `${head('ROTINA DO MÊS','Checklist de fechamento','Cada tarefa pertence a um responsável específico. O Gestor acompanha toda a equipe.')}${selector()}${roleNote()}<div class="grid cols-2"><section class="card"><div class="section-head"><div><h2>${isGestor()?'Atividades da competência':'Minhas tarefas atribuídas'}</h2><p class="section-sub">${e(c.name)} · ${e(c.month)}</p></div>${badge(`${progress(c)}% geral`,'purple')}</div><div class="progress wide mb"><i style="width:${progress(c)}%"></i></div><div class="checklist">${mine.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" data-task="${e(t.id)}" ${t.done?'checked':''} ${c.closed||!canEditTask(t)?'disabled':''} aria-label="${e(t.title)}"/><span class="t-text">${e(t.title)}<small>Responsável: ${e(t.owner||'Não atribuído')} · ${t.due?'Prazo: '+e(t.due.split('-').reverse().join('/')):'Prazo não definido'}${t.done&&t.doneAt?' · Concluída em '+e(dshort(t.doneAt)):''}</small></span>${badge(t.done?'Concluído':'Pendente',t.done?'green':'orange')}${!c.closed&&canEditTask(t)?btn('edit-task:'+t.id,'Editar','btn-outline btn-sm'):''}${isGestor()&&!c.closed?btn('delete-task:'+t.id,'Excluir','btn-danger btn-sm'):''}</div>`).join('')||empty('Nenhuma tarefa atribuída','O Gestor pode atribuir atividades a este contador.')}</div>${isGestor()&&!c.closed?`<div class="mt">${btn('add-task',`${icon('plus')} Adicionar tarefa`,'btn-outline')}</div>`:''}${c.closed?`<div class="inline-note mt">Fechamento encerrado: somente consulta.</div>`:''}</section><section class="card"><h2>Resumo das atividades</h2><p class="section-sub">${isGestor()?'Todas as tarefas do escritório para esta empresa':'Apenas tarefas do profissional selecionado'}</p><div class="grid cols-even mt">${kpi('Concluídas',mine.filter(t=>t.done).length,'De '+mine.length+' atribuída(s)','check')}${kpi('Pendentes',mine.filter(t=>!t.done).length,'Ainda precisam de conferência','alert')}</div><hr class="section-divider"/><div class="soft-callout"><b>Distribuição de responsabilidades:</b> ao transferir uma tarefa para outro contador, ela sai da lista do responsável anterior e passa a aparecer somente na lista do novo responsável. O Gestor continua acompanhando todas.</div><div class="btn-row mt">${btn('go-conferencias','Conferir saldos →','btn-primary')}${btn('go-encerramento','Ver fechamento','btn-outline')}</div></section></div>`;}
function lancamentos(){const c=current();const entries=st.entries.filter(x=>x.company===c.id);return `${head('REGISTROS','Lançamentos contábeis','Cadastre e consulte lançamentos de exemplo. Nenhum lançamento é enviado a um servidor.')}${selector()}${roleNote()}<div class="grid cols-2"><section class="card"><div class="section-head"><h2>Lançamentos da competência</h2>${badge(`${entries.length} registros`,'purple')}</div>${entries.length?`<div class="table-scroll"><table><thead><tr><th>Data</th><th>Conta</th><th>Histórico</th><th>Valor</th><th>Registrado por</th><th>Ação</th></tr></thead><tbody>${entries.map(x=>`<tr><td>${e(x.date.split('-').reverse().join('/'))}</td><td class="td-main">${e(x.account)}</td><td>${e(x.description)}</td><td class="td-main number">${brl(x.value)}</td><td>${e(x.registradoPor || 'Não informado')}</td><td>${!c.closed?btn('delete-entry:'+x.id,'Excluir','btn-danger btn-sm'):'Somente leitura'}</td></tr>`).join('')}</tbody></table></div>`:empty('Sem lançamentos','Cadastre o primeiro lançamento fictício para esta empresa.')}<div class="inline-note mt">Exemplo de valor atípico: lançamento de R$ 7.800,00 comparado a um histórico hipotético de R$ 1.200,00. Isso não comprova erro.</div></section><section class="card"><h2>Registrar lançamento fictício</h2><p class="section-sub">Teste o cadastro e observe como alertas demonstrativos podem ser gerados.</p>${c.closed?`<div class="soft-callout callout-warning mt"><b>Competência encerrada.</b> Não é possível registrar novos lançamentos neste período demonstrativo.</div>`:`<form id="entryForm" class="form-grid mt"><div class="field"><label for="entryDate">Data</label><input class="input" type="date" id="entryDate" name="date" value="2026-10-25" required></div><div class="field"><label for="entryValue">Valor (R$)</label><input class="input" type="number" id="entryValue" name="value" min="0.01" step="0.01" placeholder="Ex.: 7800" required></div><div class="field full"><label for="entryAccount">Conta contábil</label><select class="select" id="entryAccount" name="account" required><option>Despesas operacionais</option><option>Fornecedores</option><option>Receitas de serviços</option><option>Caixa e bancos</option><option>Impostos a recolher</option><option value="__other__">Outra conta (informar)</option></select><div id="otherAccountBox" class="field full hidden" style="margin-top:10px"><label for="otherAccount">Nome da conta contábil fictícia</label><input class="input" id="otherAccount" name="otherAccount" maxlength="90" placeholder="Ex.: Despesas com manutenção"></div></div><div class="field full"><label for="entryDescription">Descrição</label><input class="input" id="entryDescription" name="description" maxlength="120" placeholder="Ex.: Conta de energia do mês" required></div><div class="form-footer"><button class="btn btn-primary" type="submit">${icon('plus')} Salvar lançamento</button></div></form>`}<div class="soft-callout mt"><b>Como funciona nesta demonstração:</b> valores de despesas operacionais superiores a R$ 3.600,00 (três vezes uma referência fictícia de R$ 1.200,00) geram um alerta por regra simples. Não há execução de Z-score ou Isolation Forest.</div></section></div>`;}

function linkedAlertPanel(){const a=st.alerts.find(x=>x.id===focusedAlertId&&x.company===current().id);if(!a)return '';const entry=a.entryId?st.entries.find(x=>x.id===a.entryId):null;return `<section class="card mt" id="alerta-relacionado" style="border:1px solid #d9c5ff;box-shadow:0 4px 20px #7444d513"><div class="section-head"><div><div class="eyebrow">CONFERÊNCIA VINCULADA AO ALERTA</div><h2>${e(a.title)}</h2></div>${badge(a.status,a.status==='Pendente'?'orange':a.status==='Revisado'?'purple':'green')}</div><p>${e(a.description)}</p>${entry?`<div class="inline-note"><b>Lançamento relacionado:</b> ${e(entry.date.split('-').reverse().join('/'))} · ${e(entry.account)} · ${e(entry.description)} · <b>${brl(entry.value)}</b></div>`:`<div class="inline-note">${a.kind==='atipico'?'Lançamento de referência: exemplo fictício de R$ 7.800,00; valor habitual ilustrativo R$ 1.200,00.':'Alerta vinculado à comparação de saldos apresentada abaixo.'}</div>`}${a.note?`<p class="inline-note mt"><b>Justificativa atual:</b> ${e(a.note)}</p>`:''}<div class="btn-row mt">${a.status==='Pendente'?btn('review:'+a.id,'Analisar alerta','btn-primary'):(a.status==='Revisado'||a.status==='Resolvido')?btn('edit-review:'+a.id,a.note?'Editar justificativa':'Adicionar justificativa','btn-primary'):''}${btn('go-alertas','Voltar aos alertas','btn-outline')}</div>${a.kind==='atipico'?`<p class="fine muted mt">A análise de lançamento atípico é independente da conciliação de saldos mostrada abaixo. Um valor incomum não comprova divergência contábil.</p>`:''}</section>`;}
function conferencias(){const c=current(),diff=Math.abs(c.balance.contabil-c.balance.auxiliar),equal=diff<.00001;return `${head('VERIFICAÇÕES','Conferência de saldos','Compare o saldo contábil e o razão auxiliar. A diferença é apurada automaticamente por uma regra básica.')}${selector()}${sample}${focusedAlertId?linkedAlertPanel():''}<div class="grid cols-2 mt"><section class="card"><div class="section-head"><h2>Comparação de valores</h2>${badge(equal?'Saldos coincidentes':'Divergência identificada',equal?'green':'orange')}</div><div class="metric-compare"><div class="metric-box"><small>Saldo contábil</small><strong class="number">${brl(c.balance.contabil)}</strong></div><span class="vs">vs.</span><div class="metric-box"><small>Razão auxiliar</small><strong class="number">${brl(c.balance.auxiliar)}</strong></div></div><div class="soft-callout ${equal?'callout-success':'callout-warning'} mt">${equal?`<b>Conferência sem divergência:</b> os dois saldos informados coincidem.`:`<b>Diferença de ${brl(diff)}:</b> os saldos deveriam ser comparados e a causa investigada pelo profissional. O sistema não sabe qual registro está correto.`}</div><hr class="section-divider"/><h3>Simule uma nova conferência</h3><p class="section-sub">Altere os valores e clique em “Executar conferência”.</p><form id="balanceForm" class="form-grid mt"><div class="field"><label for="balanceAccounting">Saldo contábil (R$)</label><input class="input" type="number" id="balanceAccounting" name="contabil" min="0" step="0.01" value="${c.balance.contabil}" required ${c.closed?'disabled':''}></div><div class="field"><label for="balanceAux">Razão auxiliar (R$)</label><input class="input" type="number" id="balanceAux" name="auxiliar" min="0" step="0.01" value="${c.balance.auxiliar}" required ${c.closed?'disabled':''}></div><div class="form-footer"><button type="submit" class="btn btn-primary" ${c.closed?'disabled':''}>${icon('scan')} Executar conferência</button></div></form></section>
<section class="card"><h2>Como interpretar o resultado?</h2><div class="step-list mt"><div class="step"><span class="step-number">1</span><div><b>Compare os registros</b><p>Dois saldos referentes à mesma conta e competência devem ser conciliados.</p></div></div><div class="step"><span class="step-number">2</span><div><b>Investigue diferenças</b><p>Uma divergência pode indicar lançamento não registrado, classificação diferente ou atualização pendente.</p></div></div><div class="step"><span class="step-number">3</span><div><b>Confirme com o profissional</b><p>A ferramenta sinaliza a necessidade de revisão, mas não decide automaticamente qual valor é correto.</p></div></div></div><div class="soft-callout mt"><b>Exemplo do material de apoio:</b> R$ 4.000,00 versus R$ 6.000,00 resulta em diferença de R$ 2.000,00, independentemente de qual saldo esteja maior.</div><div class="btn-row mt">${btn('go-alertas','Ver alertas →','btn-soft')}${btn('go-encerramento','Analisar bloqueios','btn-outline')}</div></section></div>`;}
function alertCard(a){const c=company(a.company);return `<article class="card alert-card"><div class="alert-item"><div class="alert-symbol">${icon(a.kind==='saldo'?'scan':'spark')}</div><div class="alert-content"><div class="alert-meta">${badge(a.kind==='saldo'?'Divergência de saldos':'Lançamento atípico','purple')} ${badge(a.status,a.status==='Pendente'?'orange':'green')}</div><h3 style="margin:10px 0 5px">${e(a.title)}</h3><p>${e(a.description)}</p><small class="muted">${e(c?.name||'Empresa não localizada')}</small>${a.note?`<p class="inline-note mt"><b>Justificativa:</b> ${e(a.note)}</p>`:''}${historyOf(a).length?`<details class="mt"><summary class="fine text-purple" style="cursor:pointer">Histórico de justificativas (${historyOf(a).length})</summary>${historyOf(a).map(h=>`<p class="inline-note mt"><b>${e(h.actor)}</b> · ${e(dshort(h.date))}<br>${e(h.note)}</p>`).join('')}</details>`:''}</div></div><div class="btn-row">${a.status==='Pendente'?btn(`review:${a.id}`,`${icon('check')} Analisar alerta`,'btn-primary'):(a.status==='Revisado'||a.status==='Resolvido')?btn(`edit-review:${a.id}`,a.note?'Editar justificativa':'Adicionar justificativa','btn-soft'):''} ${btn(`go-alert-conferencia:${a.id}`,'Ir para conferências','btn-outline btn-sm')}</div></article>`;}
function alertas(){let alerts=filter==='Todos'?st.alerts:st.alerts.filter(a=>a.status===filter);return `${head('CONTROLE DE EXCEÇÕES','Alertas e investigação','Sinalizações são indícios para análise profissional, não diagnósticos de erros contábeis.')}${roleNote()}<div class="soft-callout mb"><b>O que é simulado?</b> Os alertas iniciais são exemplos fictícios. Um novo alerta de valor atípico pode surgir por uma regra demonstrativa simples, e a divergência de saldos é detectada por comparação direta. Nenhum modelo de aprendizado de máquina é executado aqui.</div><div class="section-head"><div class="tabs" role="group" aria-label="Filtrar alertas">${['Todos','Pendente','Revisado','Resolvido'].map(v=>`<button type="button" class="tab ${filter===v?'active':''}" data-filter="${v}">${e(v)} <span>(${v==='Todos'?st.alerts.length:st.alerts.filter(a=>a.status===v).length})</span></button>`).join('')}</div></div>${alerts.length?`<div class="grid alert-card-grid">${alerts.map(alertCard).join('')}</div>`:empty('Nenhum alerta neste filtro','Mude o filtro para visualizar outras situações.','✓')}`;}
function auditoria(){const events=st.audit.filter(canViewAudit);return `${head('RASTREABILIDADE','Histórico de auditoria','Gestor visualiza o escritório; Contador consulta apenas atividades próprias e das empresas sob sua responsabilidade.')}${roleNote()}<div class="grid cols-2"><section class="card"><div class="section-head"><h2>${isGestor()?'Registro de atividades do escritório':'Atividades relacionadas ao contador'}</h2>${badge(`${events.length} eventos`,'purple')}</div>${events.length?`<div class="audit-timeline mt">${events.map(a=>`<div class="audit-event"><b>${e(a.action)}</b><p>${e(a.detail)}</p><small>${e(a.actor)} · ${e(a.company)} · ${e(dshort(a.date))}</small></div>`).join('')}</div>`:empty('Nenhum registro disponível','As atividades das empresas sob responsabilidade do profissional aparecerão aqui.')}</section><section class="card"><h2>Rastreabilidade e permissões</h2><div class="soft-callout mt"><b>Gestor:</b> pode ver o histórico completo do escritório fictício. <b>Contador:</b> pode consultar apenas eventos próprios e de empresas que estejam atribuídas ao profissional fictício selecionado.</div><div class="soft-callout callout-warning mt"><b>Limitação:</b> essa filtragem é apenas visual e funciona no navegador. Não constitui controle de acesso seguro nem uma trilha de auditoria imutável. Essas regras deverão ser reforçadas pelo backend com autenticação real.</div></section></div>`;}
function encerramento(){const c=current(),blocks=blockers(c);return `${head('VALIDAÇÃO FINAL','Fechamento contábil mensal','Acompanhe as validações antes de concluir o fechamento do período.')}${selector()}${roleNote()}${!isGestor()&&!c.closed&&!blocks.length?`<div class="soft-callout callout-success mb"><b>Verificações concluídas:</b> o Gestor poderá revisar e encerrar o fechamento. O aviso foi gerado localmente.</div>`:''}<div class="grid cols-2"><section class="card"><div class="section-head"><h2>Competência ${e(c.month)}</h2>${badge(c.closed?'Encerrada':blocks.length?'Com pendências':'Pronta para encerramento',c.closed?'green':blocks.length?'orange':'purple')}</div><div class="progress-label"><span>Progresso do checklist</span><b>${progress(c)}%</b></div><div class="progress wide mb"><i style="width:${progress(c)}%"></i></div><div class="step-list">${[[c.tasks.every(t=>t.done),'Checklist completamente finalizado','checklist','Verificar Checklist'],[Math.abs(c.balance.contabil-c.balance.auxiliar)<.00001,'Saldos conciliados','conferencias','Verificar Saldos'],[pending(c.id).length===0,'Alertas investigados e tratados','alertas','Verificar Alertas']].map(([ok,title,page,cta])=>`<div class="result-line ${ok?'success':''}"><span class="mark">${ok?'✓':'!'}</span><div style="flex:1"><b>${title}</b><p>${ok?'Verificação atendida.':'Verificação pendente.'}</p></div>${btn('go-'+page,cta,'btn-outline btn-sm')}</div>`).join('')}</div><hr class="section-divider"/>${c.closed?`<div class="soft-callout callout-success"><b>Fechamento mensal encerrado nesta demonstração.</b> ${c.closedAt?'Data e hora: '+e(dshort(c.closedAt))+' · Responsável: '+e(c.closedBy||'Gestor fictício')+'.':''} ${c.closeEstimated?' Data de encerramento não disponível para o cenário inicial.':''} Os registros permanecem disponíveis para consulta.</div>`:blocks.length?`<div class="soft-callout callout-warning"><b>Encerramento bloqueado.</b> ${blocks.length} verificação(ões) precisam ser resolvidas.</div>`:`<div class="soft-callout callout-success"><b>Condições atendidas.</b> O Gestor pode encerrar esta competência de exemplo.</div>`}<div class="btn-row mt">${btn('close-period',`${icon('lock')} Encerrar competência`,'btn-primary',`${!isGestor()||c.closed||blocks.length?'disabled':''}`)}${btn('go-checklist','Revisar checklist','btn-outline')}</div>${!isGestor()?`<p class="fine mt">Apenas o perfil Gestor pode concluir o encerramento.</p>`:''}</section><section class="card"><h2>Verificações em aberto</h2><p class="section-sub">Pendências que impedem o encerramento da competência</p><div class="mt">${blocks.length?blocks.map((b,i)=>`<div class="result-line"><span class="mark">${i+1}</span><div><b>${e(b)}</b><p>Verifique a etapa correspondente antes de concluir.</p></div></div>`).join(''):empty('Tudo certo nesta etapa','Não foram identificados bloqueios pelas regras simuladas.','✓')}</div><div class="soft-callout mt"><b>Na aplicação definitiva,</b> as regras de encerramento precisam ser verificadas e registradas pelo backend. Aqui são apenas validações locais do navegador e não abrangem obrigações fiscais nem normas contábeis específicas.</div><div class="btn-row mt">${btn('go-conferencias','Conferir saldos','btn-soft')}${btn('go-alertas','Analisar alertas','btn-outline')}</div></section></div>`;}
function roteiro(){return `${head('TESTE GUIADO','Experimente o protótipo','O roteiro propõe atividades rápidas com dados fictícios. Você pode explorar livremente, sem seguir uma ordem obrigatória.')}
<div class="grid cols-2"><section class="card"><div class="section-head"><h2>Roteiro sugerido aos participantes</h2>${badge('Teste exploratório','purple')}</div><div class="step-list">${[
['1','Conheça o painel','Veja a quantidade de empresas, tarefas e alertas.','dashboard'],
['2','Alterne os perfis','Compare as permissões de Gestor e Contador na barra superior.','equipe'],
['3','Conclua uma tarefa','Abra o checklist da Alvorada e marque uma atividade.','checklist'],
['4','Confira a divergência','Compare R$ 6.000,00 com R$ 4.000,00; teste igualar os valores.','conferencias'],
['5','Analise um alerta','Justifique o lançamento de R$ 7.800,00, que está fora do habitual.','alertas'],
['6','Explore o encerramento','Veja quais pendências bloqueiam o fechamento do mês.','encerramento'],
['7','Registre sua opinião','Avalie facilidade de uso e clareza do protótipo.','avaliacao']
].map(([n,t,d,page])=>`<div class="step"><span class="step-number">${n}</span><div style="flex:1"><b>${t}</b><p>${d}</p></div><button type="button" class="btn btn-soft btn-sm" data-nav="${page}">Abrir →</button></div>`).join('')}</div></section>
<section class="card"><h2>Antes de começar</h2><div class="soft-callout mt"><b>1. Use apenas dados fictícios.</b> Não digite CPF, CNPJ, senhas, nomes reais, movimentações de clientes ou qualquer informação confidencial.</div><div class="soft-callout mt"><b>2. Teste com liberdade.</b> A demonstração salva as alterações apenas no seu navegador; outros participantes não veem seus dados.</div><div class="soft-callout mt"><b>3. Entenda o limite.</b> Não existem autenticação verdadeira, integração contábil, IA executando ou banco de dados compartilhado.</div><div class="soft-callout mt"><b>4. Envie sua opinião.</b> Na área “Avaliar protótipo”, faça o download das respostas ou copie o texto e encaminhe à responsável pela pesquisa pelo canal que ela informar.</div><hr class="section-divider"/><h3>Perguntas para observar durante o teste</h3><p class="fine mt">Você conseguiu entender o significado dos alertas? Encontrou facilmente o checklist? As permissões dos profissionais parecem adequadas? O que mudaria na navegação?</p><div class="btn-row mt">${btn('go-avaliacao','Avaliar agora','btn-primary')}${btn('reset','Reiniciar cenário','btn-outline')}</div></section></div>`;}
const QUESTIONS=[['q1','Foi fácil localizar as funcionalidades de que precisava.'],['q2','Os textos, indicadores e status foram claros.'],['q3','O fluxo de checklist e conferência foi fácil de compreender.'],['q4','As sinalizações de alerta ajudaram a identificar o que revisar.'],['q5','Eu conseguiria utilizar uma interface semelhante nas minhas atividades, após treinamento adequado.']];
function avaliacao(){return `${head('PESQUISA EXPLORATÓRIA','Avalie sua experiência','Após explorar as telas, registre sua percepção sobre navegação e compreensão do protótipo. Não é uma avaliação do sistema definitivo.')}
<div class="grid cols-2"><section class="card"><h2>Avaliação rápida</h2><p class="section-sub">Selecione de 1 a 5 para cada afirmação.</p><form id="feedbackForm" class="mt"><div class="score-grid">${QUESTIONS.map(([k,q],i)=>`<fieldset class="score-line"><legend>${i+1}. ${e(q)}</legend><div class="rating-options">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="${k}" value="${n}" ${st.feedback?.[k]===n?'checked':''} ${n===1?'required':''}/><span>${n}</span></label>`).join('')}</div><div class="rating-legend"><span>1 · Discordo totalmente</span><span>5 · Concordo totalmente</span></div></fieldset>`).join('')}</div><div class="field mt"><label for="feedbackLike">O que funcionou melhor? (opcional)</label><textarea class="textarea" id="feedbackLike" name="like" maxlength="900" placeholder="Conte quais partes mais ajudaram.">${e(st.feedback?.like||'')}</textarea></div><div class="field mt"><label for="feedbackImprove">O que você mudaria? (opcional)</label><textarea class="textarea" id="feedbackImprove" name="improve" maxlength="900" placeholder="Sugestões, dificuldades ou recursos ausentes.">${e(st.feedback?.improve||'')}</textarea></div><div class="form-footer mt" style="justify-content:flex-start;flex-wrap:wrap"><button class="btn btn-primary" type="submit" name="intent" value="download">${icon('message')} Baixar minhas respostas</button><button class="btn btn-outline" type="submit" name="intent" value="copy">Copiar respostas</button></div></form>${st.feedback?`<div class="feedback-done mt"><b class="text-green">✓ Respostas registradas neste navegador</b><p class="fine" style="margin:6px 0 0">Você pode atualizar suas respostas ou baixar o arquivo novamente.</p></div>`:''}</section>
<section class="card"><h2>Como suas respostas serão recebidas?</h2><p class="section-sub">A demonstração funciona sem servidor.</p><div class="step-list mt"><div class="step"><span class="step-number">1</span><div><b>Preencha a avaliação</b><p>Marque os cinco itens e, se quiser, acrescente comentários.</p></div></div><div class="step"><span class="step-number">2</span><div><b>Baixe ou copie</b><p>O sistema cria um arquivo de texto com suas respostas no próprio dispositivo, sem transmiti-las.</p></div></div><div class="step"><span class="step-number">3</span><div><b>Encaminhe à pesquisadora</b><p>Envie o arquivo ou cole o texto no canal de contato informado junto ao convite da pesquisa.</p></div></div></div><div class="soft-callout callout-warning mt"><b>Não é um formulário online de coleta.</b> Sem o envio manual do arquivo/texto, a responsável pela pesquisa não receberá suas respostas. Não inclua informações confidenciais nos comentários.</div><div class="inline-note mt">Esta é uma escala exploratória de concordância criada para o protótipo. <b>Não é o questionário SUS</b> e não deve ser analisada como uma escala padronizada de usabilidade.</div></section></div>`;}
const SCREENS={dashboard,empresas,equipe,checklist,lancamentos,conferencias,alertas,auditoria,encerramento,roteiro,avaliacao};
function render(){enforceSession();notifyReady();if(!st.userId||!st.team.some(m=>m.id===st.userId&&m.role===st.role))st.userId=st.team.find(m=>m.role===st.role)?.id;const userSelect=document.getElementById('userSelect');userSelect.innerHTML=(isLoginMode()?st.team.filter(m=>m.id===st.userId):st.team.filter(m=>m.role===st.role)).map(m=>`<option value="${e(m.id)}">${e(m.name)}</option>`).join('');userSelect.value=st.userId||'';userSelect.disabled=isLoginMode();document.getElementById('roleSelect').disabled=isLoginMode();document.querySelectorAll('[data-profile-switch]').forEach(el=>el.classList.toggle('hidden',isLoginMode()));if(!company(st.company))st.company=st.companies[0].id;if(!SCREENS[st.section])st.section='dashboard';const officeTitle=document.getElementById('officeName');if(officeTitle)officeTitle.textContent=st.officeName||OFFICE_NAMES.aurora;const crumb=document.querySelector('.crumb-office');if(crumb)crumb.textContent=st.officeName||OFFICE_NAMES.aurora;const avatar=document.getElementById('officeAvatar');if(avatar)avatar.textContent=(st.officeName||'AC').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();const monthSel=document.getElementById('periodSelect');if(monthSel){monthSel.innerHTML=MONTH_OPTIONS.map(m=>`<option value="${m}">${m}${m==='11/2026'?' · atual':''}</option>`).join('');monthSel.value=st.activeMonth||'10/2026';}const officeSel=document.getElementById('officeSelect');if(officeSel){officeSel.innerHTML=Object.entries(OFFICE_NAMES).map(([id,name])=>`<option value="${id}">${e(name)}</option>`).join('');officeSel.value=st.officeId||'aurora';officeSel.disabled=!isGestor();officeSel.title=isGestor()?'Alternar cenários fictícios de escritórios':'Somente o perfil Gestor pode trocar escritório';}const sessionLabel=document.getElementById('sessionLabel');if(sessionLabel){let ses=null;try{ses=JSON.parse(sessionStorage.getItem('fluxocontabil_demo_session_v5')||'null')}catch(_e){}sessionLabel.textContent=ses?(ses.mode==='visitor'?'Visitante':ses.label):'Sem sessão';}const currentName=document.getElementById('currentPersonName');if(currentName)currentName.textContent=activeUser()?.name||'Usuário fictício';document.getElementById('roleSelect').value=st.role;document.getElementById('crumbTitle').textContent=NAV.find(n=>n[0]===st.section)?.[1]||'Visão geral';renderNav();document.getElementById('main').innerHTML=SCREENS[st.section]();save();}
function go(section,fromHistory=false){
 if(!SCREENS[section]){if(section==='mensagens')section='roteiro';else return;}
 if(!fromHistory&&st.section!==section && !document.getElementById('app').hidden)
  history.pushState({fluxoView:'app',section},'','#'+section);
 st.section=section;render();closeMenu();
 window.scrollTo({top:0,behavior:'instant'});
 document.getElementById('main').focus({preventScroll:true});
}
window.addEventListener('fluxo-route-pop',event=>go(event.detail.section,true));
window.addEventListener('fluxo-app-open',event=>{if(!isLoginMode())enterGuestMode();else enforceSession();go(event.detail.section||'dashboard',true);});
function closeMenu(){document.getElementById('sidebar').classList.remove('open');document.getElementById('scrim').classList.remove('active');}
function openModal(title,description,inner,kind){const d=document.getElementById('modal');const f=document.getElementById('modalContent');f.innerHTML=`<div class="modal-inner"><button type="button" class="modal-close" data-action="close-modal" aria-label="Fechar">×</button><h2>${e(title)}</h2><p>${e(description)}</p><div class="form-grid">${inner}</div><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">Confirmar</button></div></div>`;f.dataset.kind=kind;d.showModal();const first=f.querySelector('input,textarea,select');if(first)first.focus();}
function closeModal(){document.getElementById('modal').close();}
function modalFor(act){if(act==='new-group'){const me=activeUser();const possible=st.team.filter(m=>m.id!==me?.id);openModal('Criar grupo da equipe','Qualquer integrante pode criar grupos fictícios. Selecione os participantes.',`<div class="field full"><label>Nome do grupo</label><input class="input" name="groupName" maxlength="60" required placeholder="Ex.: Fechamento de novembro"/></div><div class="field full"><label>Adicionar integrantes</label>${possible.map(m=>`<label class="chat-member-option"><input type="checkbox" name="members" value="${e(m.id)}"/> ${e(m.name)} · ${e(m.role)}</label>`).join('')}</div>`,'new-group');return;}
if(act.startsWith('group-members:')){const g=st.groups?.find(x=>x.id===act.slice(14));if(!g||!g.members.includes(activeUser()?.id))return;openModal('Integrantes — '+g.name,'Qualquer participante pode adicionar membros ao grupo demonstrativo.',`<div class="field full"><b>Membros atuais</b>${g.members.map(id=>`<p class="fine">${e(st.team.find(m=>m.id===id)?.name||'Integrante retirado')}</p>`).join('')}</div><div class="field full"><label>Adicionar integrantes</label>${st.team.filter(m=>!g.members.includes(m.id)).map(m=>`<label class="chat-member-option"><input type="checkbox" name="members" value="${e(m.id)}"/> ${e(m.name)}</label>`).join('')||'<span>Todos já participam.</span>'}</div>`,'group-members:'+g.id);return;}
if(act.startsWith('member-profile:')){const m=st.team.find(x=>x.id===act.slice(15));if(!m||(!isGestor()&&m.id!==st.userId))return;const owned=st.companies.filter(c=>c.responsavel===m.name);const tasksOwned=st.companies.flatMap(c=>c.tasks.filter(t=>t.owner===m.name));openModal('Perfil profissional — '+m.name,'Somente informações profissionais fictícias, sem dados sensíveis ou credenciais.',`<div class="field full"><b>Função:</b> ${m.role==='GESTOR'?'Gestor':'Contador'}</div><div class="field full"><b>Especialidade:</b> ${e(m.specialty||'Não informada')}</div><div class="field full"><b>Apresentação profissional:</b> ${e(m.publicBio||'Nenhuma descrição cadastrada')}</div><div class="field full"><b>Empresas sob responsabilidade:</b> ${e(owned.map(c=>c.name).join(', ')||'Nenhuma')}</div><div class="field full"><b>Tarefas atribuídas:</b> ${tasksOwned.length} (${tasksOwned.filter(t=>t.done).length} concluídas)</div>${isGestor()?`<div class="field full">${btn('edit-profile:'+m.id,'Editar informações profissionais','btn-outline btn-sm')}</div>`:''}`,'view-only');return;}if(act.startsWith('edit-profile:')&&isGestor()){const m=st.team.find(x=>x.id===act.slice(13));if(!m)return;if(document.getElementById('modal').open)closeModal();openModal('Editar perfil profissional — '+m.name,'Somente informações profissionais fictícias.',`<div class="field full"><label>Especialidade</label><input class="input" name="specialty" maxlength="90" value="${e(m.specialty||'')}"/></div><div class="field full"><label>Apresentação profissional</label><textarea class="textarea" name="publicBio" maxlength="300">${e(m.publicBio||'')}</textarea></div>`,'profile:'+m.id);return;}if(act==='add-company'&&isGestor())openModal('Nova empresa-cliente','Cadastre uma empresa fictícia para testar o fluxo.',`<div class="field full"><label for="newCompany">Nome fictício da empresa</label><input class="input" id="newCompany" name="name" maxlength="85" placeholder="Ex.: Estrela Comércio Ltda." required></div><div class="field"><label for="newSector">Segmento</label><select class="select" id="newSector" name="sector"><option>Comércio</option><option>Serviços</option><option>Indústria</option><option>Outro</option></select></div><div class="field"><label for="newOwner">Responsável</label><select class="select" id="newOwner" name="owner">${st.team.filter(m=>m.role==='CONTADOR').map(m=>`<option value="${e(m.name)}">${e(m.name)}</option>`).join('')}</select></div>`,'company');
else if(act==='add-member'&&isGestor())openModal('Novo funcionário fictício','Adicionar um membro demonstrativo à equipe.',`<div class="field full"><label for="newMember">Nome fictício</label><input class="input" id="newMember" name="name" maxlength="70" placeholder="Ex.: Ana Souza" required></div><div class="field full"><label for="newRole">Perfil</label><select class="select" id="newRole" name="role"><option value="CONTADOR">Contador</option><option value="GESTOR">Gestor</option></select></div>`,'member');
else if(act.startsWith('change-owner:')&&isGestor()){const c=company(act.slice(13));if(!c)return;const users=st.team.filter(m=>m.role==='CONTADOR');if(!users.length)return toast('Cadastre um contador antes de atribuir responsável.');openModal('Alterar responsável','Selecione o contador responsável pelo fechamento desta empresa fictícia.',`<div class="field full"><label for="assignedOwner">Responsável</label><select class="select" name="owner" id="assignedOwner">${users.map(m=>`<option value="${e(m.name)}" ${m.name===c.responsavel?'selected':''}>${e(m.name)}</option>`).join('')}</select></div>`,'change-owner:'+c.id);}
else if(act==='add-task'&&isGestor()&&!current().closed)openModal('Adicionar tarefa','Crie uma atividade fictícia para o checklist da empresa selecionada.',`<div class="field full"><label for="newTask">Descrição da tarefa</label><input class="input" id="newTask" name="title" maxlength="90" placeholder="Ex.: Conferir documentos recebidos" required></div><div class="field"><label for="taskOwner">Responsável</label><select class="select" name="owner" id="taskOwner">${st.team.map(m=>`<option value="${e(m.name)}">${e(m.name)}</option>`).join('')}</select></div><div class="field"><label for="taskDue">Prazo (opcional)</label><input class="input" type="date" name="due" id="taskDue"></div>`,'task');
else if(act.startsWith('edit-task:')&&!current().closed){const t=current().tasks.find(x=>x.id===act.slice(10));if(!t||!canEditTask(t))return;openModal('Editar tarefa','Ajuste o responsável e o prazo do checklist. Os dados são apenas ilustrativos.',`<div class="field full"><label>Descrição</label><input class="input" name="title" required maxlength="90" value="${e(t.title)}"></div><div class="field"><label>Responsável</label><select class="select" name="owner"><option value="">Não atribuído</option>${st.team.map(m=>`<option value="${e(m.name)}" ${m.name===t.owner?'selected':''}>${e(m.name)}</option>`).join('')}</select></div><div class="field"><label>Prazo</label><input class="input" type="date" name="due" value="${e(t.due||'')}"></div>`,'edit-task:'+t.id);}
else if(act.startsWith('review:')||act.startsWith('edit-review:')){const editing=act.startsWith('edit-review:');const a=st.alerts.find(x=>x.id===act.slice(editing?12:7));if(!a||(editing?!['Revisado','Resolvido'].includes(a.status):a.status!=='Pendente')||company(a.company)?.closed)return;openModal(editing?'Editar justificativa do alerta':'Registrar análise do alerta',`${a.title}. A justificativa será registrada no histórico demonstrativo.`,`<div class="field full"><label for="reviewNote">Justificativa da análise (mínimo 8 caracteres)</label><textarea class="textarea" id="reviewNote" name="note" minlength="8" maxlength="700" placeholder="Ex.: O lançamento foi conferido com documentação fictícia." required>${e(editing?a.note:'')}</textarea></div><div class="soft-callout full">Alterações mantêm a versão anterior no histórico local. A auditoria desta demonstração não é inviolável e não substitui o backend. A análise não altera automaticamente saldos ou lançamentos.</div>`,(editing?'edit-review:':'review:')+a.id);}
}
function formModalSubmit(ev){ev.preventDefault();const f=ev.target,fd=new FormData(f),kind=f.dataset.kind,c=current();if(kind==='view-only'){closeModal();return;}
if(kind==='new-group'){const name=String(fd.get('groupName')||'').trim();const members=[...new Set([activeUser()?.id,...fd.getAll('members')].filter(id=>st.team.some(m=>m.id===id)))];if(name.length<3||members.length<2)return toast('Informe o nome e selecione pelo menos um outro integrante.');const g={id:uid(),name,members,createdBy:activeUser().id,createdAt:new Date().toISOString()};st.groups??=[];st.groups.push(g);st.chatChannel='group:'+g.id;log('Criação de grupo',`Grupo fictício ${g.name} criado com ${members.length} integrantes.`);closeModal();render();return toast('Grupo criado neste navegador.');}
if(kind.startsWith('group-members:')){const g=st.groups?.find(x=>x.id===kind.slice(14));if(!g||!g.members.includes(activeUser()?.id))return;const added=fd.getAll('members').filter(id=>st.team.some(m=>m.id===id));g.members=[...new Set([...g.members,...added])];log('Inclusão em grupo',`${added.length} integrante(s) adicionados ao grupo ${g.name}.`);closeModal();render();return toast('Integrantes atualizados localmente.');}if(kind.startsWith('profile:')&&isGestor()){const m=st.team.find(x=>x.id===kind.slice(8));if(!m)return;m.specialty=String(fd.get('specialty')||'').trim().slice(0,90);m.publicBio=String(fd.get('publicBio')||'').trim().slice(0,300);log('Atualização de perfil profissional',`Dados profissionais demonstrativos de ${m.name} atualizados.`);toast('Perfil profissional atualizado.');}
else if(kind==='company'&&isGestor()){const name=String(fd.get('name')||'').trim();if(name.length<3)return toast('Informe um nome fictício válido.');const comp={id:uid(),name,sector:String(fd.get('sector')),responsavel:String(fd.get('owner')),month:st.activeMonth||'10/2026',closed:false,tasks:tasks(uid(),0),balance:{contabil:0,auxiliar:0}};st.companies.push(comp);st.company=comp.id;log('Cadastro de empresa-cliente','Empresa fictícia adicionada à carteira.',comp);toast('Empresa fictícia cadastrada.');}
else if(kind==='member'&&isGestor()){const name=String(fd.get('name')||'').trim();if(name.length<3)return toast('Informe um nome fictício válido.');st.team.push({id:uid(),name,role:String(fd.get('role'))});log('Cadastro de funcionário',`Novo integrante fictício: ${name}.`);toast('Funcionário fictício incluído.');}
else if(kind.startsWith('change-owner:')&&isGestor()){const c=company(kind.slice(13)),owner=String(fd.get('owner')||'');if(!c||!st.team.some(m=>m.name===owner&&m.role==='CONTADOR'))return toast('Selecione um contador válido.');const previous=c.responsavel;c.responsavel=owner;log('Reatribuição de empresa',`Responsável anterior: ${previous}; atual: ${owner}.`,c);toast('Responsável atualizado.');}
else if(kind==='task'&&isGestor()&&!c.closed){const title=String(fd.get('title')||'').trim();if(title.length<3)return toast('Descreva a tarefa.');c.tasks.push({id:uid(),title,done:false,owner:String(fd.get('owner')||''),due:String(fd.get('due')||'')});log('Criação de tarefa',`Tarefa adicionada: ${title}.`,c);toast('Tarefa adicionada.');}
else if(kind.startsWith('edit-task:')&&!c.closed){const t=c.tasks.find(x=>x.id===kind.slice(10));if(!t||!canEditTask(t))return toast('Tarefa não autorizada para este perfil.');const title=String(fd.get('title')||'').trim(),owner=String(fd.get('owner')||''),due=String(fd.get('due')||'');if(title.length<3||owner&&!st.team.some(m=>m.name===owner))return toast('Dados da tarefa inválidos.');if(!isGestor()&&owner!==t.owner)return toast('Somente Gestor pode transferir tarefas.');const prior=t.owner;t.title=title;t.owner=owner;t.due=due;if(prior!==owner){t.done=false;t.doneAt=null;}log('Edição de tarefa',`Tarefa atualizada: ${title}; responsável: ${owner||'não atribuído'}; prazo: ${due||'não informado'}.`,c);toast('Tarefa atualizada.');}
else if(kind.startsWith('review:')||kind.startsWith('edit-review:')){const editing=kind.startsWith('edit-review:');const a=st.alerts.find(x=>x.id===kind.slice(editing?12:7));const note=String(fd.get('note')||'').trim();if(!a||company(a.company)?.closed||(editing?!['Revisado','Resolvido'].includes(a.status):a.status!=='Pendente')||note.length<8)return toast('Informe uma justificativa válida com pelo menos 8 caracteres.');if(editing&&note===a.note)return toast('Altere o texto antes de confirmar.');if(a.note){a.noteHistory=historyOf(a);a.noteHistory.push({note:a.note,date:new Date().toISOString(),actor:actor()});}if(a.status==='Pendente')a.status='Revisado';a.note=note;log(editing?'Edição de justificativa':'Revisão de alerta',`${a.title}: ${editing?'justificativa alterada (versão anterior preservada)':'justificativa registrada'}.`,company(a.company));toast(editing?'Justificativa atualizada e histórico preservado.':'Análise registrada.');}
else return;closeModal();render();}
function handleBalance(fd){const c=current();if(c.closed)return toast('Esta competência já foi encerrada.');const contabil=Number(fd.get('contabil')),auxiliar=Number(fd.get('auxiliar'));if(!Number.isFinite(contabil)||!Number.isFinite(auxiliar)||contabil<0||auxiliar<0)return toast('Informe saldos válidos.');const changed=c.balance.contabil!==contabil||c.balance.auxiliar!==auxiliar;c.balance={contabil,auxiliar};const diff=Math.abs(contabil-auxiliar);let a=st.alerts.find(x=>x.company===c.id&&x.kind==='saldo');if(diff>=.00001){const desc=`Saldo contábil de ${brl(contabil)} e razão auxiliar de ${brl(auxiliar)}. Diferença de ${brl(diff)}.`;if(a){a.description=desc;if(changed){if(a.note){a.noteHistory=historyOf(a);a.noteHistory.push({note:a.note,date:new Date().toISOString(),actor:actor()});}a.status='Pendente';a.note='';}}else st.alerts.push({id:uid(),company:c.id,kind:'saldo',title:'Divergência entre saldos',description:desc,status:'Pendente',note:''});}else if(a){a.status='Resolvido';a.note='Saldos coincidentes após nova conferência demonstrativa.';}
log('Conferência de saldos',diff?`Diferença de ${brl(diff)} sinalizada.`:'Saldos coincidentes na comparação.',c);render();toast(diff?'Diferença identificada. Verifique os alertas.':'Saldos coincidentes. Conferência registrada.');}
function handleEntry(fd){const c=current();if(c.closed)return toast('Competência encerrada: lançamento bloqueado.');const date=String(fd.get('date')||''),value=Number(fd.get('value')),desc=String(fd.get('description')||'').trim(),account=String(fd.get('account'))==='__other__'?String(fd.get('otherAccount')||'').trim():String(fd.get('account')||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||value<=0||!Number.isFinite(value)||desc.length<3||account.length<3)return toast('Confira os campos do lançamento e a conta contábil.');const entryId=uid();st.entries.unshift({
  id: entryId,
  company: c.id,
  date,
  account,
  description: desc,
  value,
  registradoPor: activeUser()?.name || 'Não identificado',
  registradoEm: new Date().toISOString()
});log('Cadastro de lançamento',`${desc}: ${brl(value)}.`,c);if(account==='Despesas operacionais'&&value>3600){st.alerts.unshift({id:uid(),company:c.id,kind:'atipico',entryId,title:'Lançamento acima da referência',description:`Despesa de ${brl(value)} acima de três vezes a referência ilustrativa de R$ 1.200,00. Verifique o lançamento.`,status:'Pendente',note:''});toast('Lançamento registrado e alerta demonstrativo gerado.');}else toast('Lançamento fictício registrado.');render();}
const feedbackText=(f)=>`AVALIAÇÃO EXPLORATÓRIA DO PROTÓTIPO — TCC\nSistema Inteligente para Fechamento Contábil Mensal\nData de geração: ${new Date().toLocaleString('pt-BR')}\nAmbiente: demonstração com dados fictícios, sem coleta automática\n\nEscala: 1 = Discordo totalmente; 5 = Concordo totalmente\n\n${QUESTIONS.map(([k,q],i)=>`${i+1}. ${q}\nResposta: ${f[k]}/5`).join('\n\n')}\n\nO que funcionou melhor?\n${f.like||'(Sem comentário)'}\n\nO que você mudaria?\n${f.improve||'(Sem comentário)'}\n\nObservação: este questionário não é a escala SUS. Os dados foram gerados no próprio dispositivo e precisam ser enviados manualmente à pesquisadora.`;
async function handleFeedback(ev){ev.preventDefault();const fd=new FormData(ev.target),data={like:String(fd.get('like')||'').trim(),improve:String(fd.get('improve')||'').trim()};for(const [k] of QUESTIONS){const v=Number(fd.get(k));if(!Number.isInteger(v)||v<1||v>5)return toast('Avalie as cinco afirmações antes de continuar.');data[k]=v;}st.feedback=data;save();const report=feedbackText(data);const intent=ev.submitter?.value||'download';if(intent==='copy'){try{await navigator.clipboard.writeText(report);toast('Respostas copiadas. Agora encaminhe-as à pesquisadora.');}catch(_err){const area=document.createElement('textarea');area.value=report;area.style.position='fixed';area.style.left='-99999px';document.body.appendChild(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'Respostas copiadas. Encaminhe-as à pesquisadora.':'Não foi possível copiar. Use a opção de baixar arquivo.');}}else{const blob=new Blob([report],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='avaliacao_prototipo_fechamento_tcc.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Arquivo gerado. Envie-o manualmente à pesquisadora.');}render();}
function handleClosePeriod(){const c=current();if(!isGestor())return toast('Apenas o Gestor pode encerrar a competência.');if(c.closed)return toast('Competência já encerrada.');const b=blockers(c);if(b.length)return toast(`Existem ${b.length} pendências impedindo o encerramento.`);if(!confirm(`Encerrar a competência ${c.month} de ${c.name} nesta demonstração?`))return;c.closed=true;c.closedAt=new Date().toISOString();c.closedBy=actor();c.closeEstimated=false;log('Conclusão do fechamento mensal',`Competência ${c.month} encerrada após verificações simuladas.`,c);render();toast('Competência fictícia encerrada.');}
function handleReset(){if(!confirm('Reiniciar a demonstração? Todos os dados fictícios editados e avaliações salvas neste navegador serão apagados.'))return;st=fresh();st.officeId='aurora';st.officeName=OFFICE_NAMES.aurora;st.userId='u1';officeStates={aurora:st,nova:createSecondOffice()};enforceSession();focusedAlertId=null;filter='Todos';save();render();toast('Cenário fictício restaurado.');}
document.addEventListener('click',ev=>{const channel=ev.target.closest('[data-chat-channel]');if(channel)return;const emoji=ev.target.closest('[data-emoji]');if(emoji){const field=document.getElementById('chatMessage');if(field){field.value+=emoji.dataset.emoji;field.focus();}return;}const nav=ev.target.closest('[data-nav]');if(nav){focusedAlertId=null;go(nav.dataset.nav);return;}const comp=ev.target.closest('[data-company-open]');if(comp){st.company=comp.dataset.companyOpen;go('checklist');return;}const filt=ev.target.closest('[data-filter]');if(filt){filter=filt.dataset.filter;render();return;}const el=ev.target.closest('[data-action]');if(!el)return;const act=el.dataset.action;if(act==='call:audio'||act==='call:video')return; if(act==='call:audio'||act==='call:video'){const kind=act.endsWith('video')?'video':'audio';const target=st.chatChannel||'';const name=target.startsWith('group:')?(st.groups?.find(g=>'group:'+g.id===target)?.name||'Grupo'):(st.team.find(m=>'dm:'+m.id===target)?.name||'Contato');st.calls??=[];st.calls.push({id:uid(),by:activeUser()?.id,target,name,type:kind,date:new Date().toISOString(),status:'simulação'});log('Simulação de chamada',`Tentativa demonstrativa de chamada de ${kind==='video'?'vídeo':'voz'}: ${name}. Nenhuma conexão estabelecida.`);openModal('Chamada '+(kind==='video'?'de vídeo':'de voz'),'Demonstração visual — não é uma chamada de verdade.',`<div class="field full chat-call-demo"><div style="font-size:38px">${kind==='video'?'▣':'☎'}</div><h2>${e(name)}</h2><p>Somente uma prévia de chamadas. Não utiliza câmera, microfone nem conecta outros dispositivos.</p></div>`,'view-only');return;}
if(act==='menu-toggle'){document.getElementById('sidebar').classList.toggle('open');document.getElementById('scrim').classList.toggle('active');}else if(act==='menu-close')closeMenu();else if(act==='close-modal')closeModal();else if(act==='reset')handleReset();else if(act==='close-period')handleClosePeriod();else if(act.startsWith('remove-member:')){if(!isGestor())return toast('Somente Gestor pode retirar funcionários.');const id=act.slice(14),m=st.team.find(x=>x.id===id);if(!m)return;if(m.id===st.userId)return toast('Não é possível retirar o usuário fictício atualmente selecionado.');if(m.role==='GESTOR'&&st.team.filter(x=>x.role==='GESTOR').length<=1)return toast('O escritório precisa manter pelo menos um gestor.');const assigned=st.companies.filter(c=>c.responsavel===m.name),tasksAssigned=st.companies.flatMap(c=>c.tasks.filter(t=>t.owner===m.name));if(assigned.length||tasksAssigned.length)return toast(`Reatribua antes ${assigned.length} empresa(s) e ${tasksAssigned.length} tarefa(s) vinculada(s) a ${m.name}.`);if(!confirm(`Retirar ${m.name} (${m.role==='GESTOR'?'Gestor':'Contador'}) da equipe fictícia de ${st.officeName}?`))return;st.team=st.team.filter(x=>x.id!==m.id);log('Retirada de integrante',`${m.name} removido da equipe demonstrativa.`);render();toast('Integrante retirado da equipe.');}
else if(act.startsWith('delete-task:')){const c=current(),id=act.slice(12),t=c.tasks.find(x=>x.id===id);if(c.closed||!t||!isGestor())return;if(!confirm(`Excluir a tarefa fictícia “${t.title}”?`))return;c.tasks=c.tasks.filter(x=>x.id!==id);log('Exclusão de tarefa',`Tarefa excluída: ${t.title}.`,c);render();toast('Tarefa excluída.');}else if(act.startsWith('delete-entry:')){const c=current(),id=act.slice(13),x=st.entries.find(y=>y.id===id&&y.company===c.id);if(c.closed||!x)return;const linked=st.alerts.filter(a=>a.entryId===id);if(!confirm(`Excluir o lançamento de ${brl(x.value)}? ${linked.length?`Também serão removidos ${linked.length} alerta(s) diretamente vinculado(s).`:''}`))return;st.entries=st.entries.filter(y=>y.id!==id);st.alerts=st.alerts.filter(a=>a.entryId!==id);if(!st.alerts.some(a=>a.id===focusedAlertId))focusedAlertId=null;log('Exclusão de lançamento',`Lançamento excluído: ${x.description} (${brl(x.value)}). ${linked.length} alerta(s) vinculado(s) removido(s).`,c);render();toast('Lançamento excluído e alertas vinculados atualizados.');}else if(act.startsWith('go-alert-conferencia:')){const a=st.alerts.find(x=>x.id===act.slice(21));if(!a)return;st.company=a.company;focusedAlertId=a.id;go('conferencias');}else if(act.startsWith('go-')){focusedAlertId=null;go(act.slice(3));}else modalFor(act);});
document.addEventListener('change',ev=>{if(ev.target.id==='periodSelect'){switchMonth(ev.target.value);}else if(ev.target.id==='officeSelect'){switchOffice(ev.target.value);}else if(ev.target.id==='roleSelect'){if(isLoginMode()){enforceSession();render();return toast('Troca de perfil permitida apenas no modo Visitante.');}st.role=ev.target.value==='CONTADOR'?'CONTADOR':'GESTOR';st.userId=st.team.find(m=>m.role===st.role)?.id;render();toast(`Perfil de demonstração: ${st.role==='GESTOR'?'Gestor':'Contador'}.`);}else if(ev.target.id==='userSelect'){if(isLoginMode()){enforceSession();render();return toast('Sua conta utiliza somente seu próprio perfil.');}const m=st.team.find(x=>x.id===ev.target.value&&x.role===st.role);if(m){st.userId=m.id;log('Troca de usuário fictício',`Perfil selecionado: ${m.name}.`);render();toast(`Usuário demonstrativo: ${m.name}.`);}}else if(ev.target.id==='entryAccount'){const other=document.getElementById('otherAccountBox');if(other){other.classList.toggle('hidden',ev.target.value!=='__other__');document.getElementById('otherAccount').required=ev.target.value==='__other__';}}else if(ev.target.id==='chatTarget'){st.chatTarget=ev.target.value;render();}else if(ev.target.id==='companySelect'){st.company=ev.target.value;render();}else if(ev.target.matches('[data-task]')){const c=current();if(c.closed){render();return toast('A competência está encerrada.');}const t=c.tasks.find(x=>x.id===ev.target.dataset.task);if(!t||!canEditTask(t)){render();return toast('Somente o responsável ou o Gestor pode atualizar esta tarefa.');}t.done=ev.target.checked;t.doneAt=t.done?new Date().toISOString():null;log(t.done?'Conclusão de tarefa':'Reabertura de tarefa',`${t.title}: ${t.done?'concluída':'pendente'}.`,c);render();toast(t.done?'Tarefa marcada como concluída.':'Tarefa marcada como pendente.');}});
document.addEventListener('submit',ev=>{if(ev.target.id==='modalContent')return formModalSubmit(ev);if(ev.target.id==='balanceForm'){ev.preventDefault();return handleBalance(new FormData(ev.target));}if(ev.target.id==='entryForm'){ev.preventDefault();return handleEntry(new FormData(ev.target));}if(ev.target.id==='feedbackForm')return handleFeedback(ev);if(ev.target.id==='chatForm'){ev.preventDefault();const body=String(new FormData(ev.target).get('body')||'').trim();const me=activeUser();const channel=st.chatChannel||'';const group=channel.startsWith('group:')?st.groups?.find(g=>'group:'+g.id===channel&&g.members.includes(me?.id)):null;const other=channel.startsWith('dm:')?st.team.find(m=>'dm:'+m.id===channel&&m.id!==me?.id):null;if((!group&&!other)||!body||body.length>500)return toast('Confira o destinatário e a mensagem.');st.messages??=[];st.messages.push({id:uid(),from:me.id,...(group?{groupId:group.id}:{to:other.id}),body,date:new Date().toISOString()});log('Mensagem local',`Mensagem fictícia para ${group?.name||other?.name}; sem envio remoto.`);render();toast('Mensagem salva neste navegador (não enviada remotamente).');}});
document.addEventListener('input',ev=>{if(ev.target.id==='chatSearch'){const q=ev.target.value.toLocaleLowerCase('pt-BR');document.querySelectorAll('.chat-contact').forEach(x=>{x.hidden=!x.textContent.toLocaleLowerCase('pt-BR').includes(q);});}});
document.getElementById('modal').addEventListener('click' ,ev=>{if(ev.target===ev.currentTarget)closeModal();});
render();
})();
